pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address payable target, uint256 amount) public {
        vm.deal(address(c), 0);
        vm.deal(address(this), 1 ether);

        uint256 countBefore = c.depositsCount();

        c.sendMoney(target, amount);

        uint256 countAfter = c.depositsCount();

        // The property: depositsCount must not increase if amount is zero (because the receive function will reject zero deposits in the mutant, but in the reference it will accept them)
        // Actually, we need a property that distinguishes P and M.
        // In P: receive() always accepts (depositsCount++). In M: receive() rejects zero (depositsCount unchanged).
        // So for a non-zero amount, both increment. For zero amount, P increments, M does not.
        // Therefore: if amount == 0, then after a sendMoney call, depositsCount must have increased (to catch M).
        assertTrue(amount > 0 || countAfter > countBefore);
    }
}

