pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address target, uint256 value) public {
        // Record initial depositsCount
        uint256 initialCount = c.depositsCount();
        // Track number of expected successful receives
        uint256 expectedReceives = 0;

        // Execute a random number of prior sends via sendMoney
        uint256 numSends = bound(uint256(keccak256(abi.encode(target, value))), 0, 5);
        for (uint256 i = 0; i < numSends; i++) {
            // Use vm.deal to fund the contract if needed
            vm.deal(address(c), address(c).balance + 1 ether);
            (bool success, ) = address(c).call{value: 0}(""); // empty call triggers receive
            if (success) {
                expectedReceives++;
                c.depositsCount(); // to advance state
            }
        }

        // Now call sendMoney (the final call)
        vm.deal(address(c), address(c).balance + value);
        (bool sendSuccess, ) = address(c).call{value: value}(abi.encodeWithSignature("sendMoney(address,uint256)", target, value));

        // If sendMoney succeeded, it triggers receive with value > 0 -> depositsCount increments
        if (sendSuccess && value > 0) {
            expectedReceives++;
        }

        uint256 finalCount = c.depositsCount();
        // The rule: depositsCount after all calls equals initialCount plus number of successful receive() calls
        assertTrue(finalCount == initialCount + expectedReceives);
    }
}

