import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 seed, address target, uint256 value) public {
        // Bound value to avoid overflow issues
        vm.assume(value <= address(c).balance);

        // First, send some ETH to the contract via receive() to increase depositsCount
        // We do this by calling sendMoney to ourselves or using deal to simulate
        vm.deal(address(c), seed); // Set initial balance

        // Now call sendMoney which will fail if value > balance, but we've assumed it's fine
        // The key is: before sendMoney, we need depositsCount to be non-zero
        // We can create a situation where depositsCount is already incremented

        // Simulate receiving ETH by calling the fallback via a self-destruct or by using cheatcodes
        // Actually, let's just do a direct call to receive() via address(c).call{value: 1}("")

        // Record depositsCount before the sendMoney call
        uint countBefore = c.depositsCount();

        // Perform the sendMoney call
        c.sendMoney(target, value);

        // After sendMoney, depositsCount should remain unchanged (since sendMoney doesn't modify it)
        // But this is true for both reference and mutant — not a good property

        // Instead: simulate a receive() call before sendMoney
        // The property: if we call receive() first, depositsCount increments correctly
        // Actually, we need a property that holds for the reference but fails for the mutant

        // Better property: depositsCount is always >= the number of times we sent ETH to the contract
        // via receive() without triggering the require check

        // Let's reset and think: the mutant removes the require, so it always increments
        // The reference only increments if (depositsCount + 1) >= depositsCount (always true unless overflow)
        // So the difference is only on overflow? No, that's impossible — the check is always true

        // Wait — the require checks for overflow. If depositsCount reaches uint max, the reference reverts
        // while the mutant increments (causing overflow wrap)

        // So the property: depositsCount should never overflow (i.e., never wrap to a lower value)

        uint prevCount = c.depositsCount();
        // Force a receive() call via low-level call
        (bool success,) = address(c).call{value: 0}("");

        // After receive(), depositsCount should be prevCount + 1 (no overflow)
        assertTrue(c.depositsCount() == prevCount + 1 || prevCount == type(uint).max);
    }
}

